import{_ as o,c as e,o as t,a4 as c}from"./chunks/framework.BYxathSa.js";const f=JSON.parse('{"title":"Q20：什么是跨域？如何解决？","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q20.md","filePath":"frontend/q20.md","lastUpdated":null}'),d={name:"frontend/q20.md"},r=c('<h1 id="q20-什么是跨域-如何解决" tabindex="-1">Q20：什么是跨域？如何解决？ <a class="header-anchor" href="#q20-什么是跨域-如何解决" aria-label="Permalink to &quot;Q20：什么是跨域？如何解决？&quot;">​</a></h1><p><strong>同源策略</strong>：浏览器最重要的安全机制，要求协议、域名、端口号完全相同。三者任一不同即为跨域。跨域时，请求可以发出，但浏览器会拦截响应，除非使用了跨域方案。</p><p><strong>常用解决方案</strong>：</p><ol><li><p><strong>CORS（跨域资源共享）</strong><br> 主流方案，由服务端设置响应头：</p><ul><li><code>Access-Control-Allow-Origin: *</code> 或特定域。</li><li>复杂请求时，会先发出一个 <code>OPTIONS</code> 预检请求，确认允许再发正式请求。可配 <code>Access-Control-Allow-Methods</code> 等。</li></ul></li><li><p><strong>JSONP（JSON with Padding）</strong><br> 利用 <code>&lt;script&gt;</code> 标签没有跨域限制的特点。通过动态创建 <code>&lt;script&gt;</code>，在 URL 后加 <code>?callback=handle</code>，服务端返回 <code>handle(data)</code> 的脚本，页面则调用 <code>handle</code> 函数拿到数据。<strong>只支持 GET 请求，有安全隐患，需前后端配合。</strong></p></li><li><p><strong>代理服务器</strong><br> 开发环境常用 devServer 的 <code>proxy</code> 配置，将 API 请求转发到目标服务器，绕过浏览器同源限制。生产环境也用 Nginx 反向代理。</p></li><li><p><strong>其他</strong>：<code>WebSocket</code>（不受同源限制）、<code>postMessage</code>（不同窗口间通信）、<code>document.domain + iframe</code>（仅限主域相同）。</p></li></ol>',4),n=[r];function s(a,l,i,p,_,g){return t(),e("div",null,n)}const m=o(d,[["render",s]]);export{f as __pageData,m as default};
